const searchLandlordPeople = `-- name: SearchLandlordPeople :many
SELECT u.id, u.full_name, u.email
FROM users u
WHERE u.status = 'active'
  AND EXISTS (SELECT 1 FROM contracts c WHERE c.tenant_id = u.id AND c.landlord_id = $1 AND c.status = 'active'
              AND c.confirmed_at IS NOT NULL AND c.deleted_at IS NULL)
  AND ($2::text = '' OR lower(u.full_name) LIKE '%' || $2::text || '%' ESCAPE '\' OR lower(u.email) LIKE '%' || $2::text || '%' ESCAPE '\')
ORDER BY u.full_name, u.id
LIMIT $4 OFFSET $3
`

type SearchLandlordPeopleParams struct {
	LandlordID uuid.UUID
	Search     string
	PageOffset int32
	PageLimit  int32
}

type SearchLandlordPeopleRow struct {
	ID       uuid.UUID
	FullName string
	Email    *string
}

// The running tenants of a landlord whose name or email contains @search (lowercase, % and _ escaped).
func (q *Queries) SearchLandlordPeople(ctx context.Context, arg SearchLandlordPeopleParams) ([]SearchLandlordPeopleRow, error) {
	rows, err := q.db.Query(ctx, searchLandlordPeople,
		arg.LandlordID,
		arg.Search,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchLandlordPeopleRow
	for rows.Next() {
		var i SearchLandlordPeopleRow
		if err := rows.Scan(&i.ID, &i.FullName, &i.Email); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

