const updateAnnouncement = `-- name: UpdateAnnouncement :execrows
UPDATE announcements SET
    sender_role = $1::text, audience = $2::text, targeting = $3::jsonb, type = $4::text,
    title = $5::jsonb, body = $6::jsonb, send_notification = $7::boolean, show_popup = $8::boolean,
    starts_at = $9::timestamptz, ends_at = $10::timestamptz, frequency = $11::text,
    frequency_days = $12::smallint, max_per_period = $13::smallint,
    max_total = $14::smallint, priority = $15::smallint, popup_size = $16::text,
    cta_label = $17::jsonb, cta_url = $18::text, revision = $19::integer, updated_at = now()
WHERE id = $20
`

type UpdateAnnouncementParams struct {
	SenderRole       string
	Audience         string
	Targeting        []byte
	Type             string
	Title            []byte
	Body             []byte
	SendNotification bool
	ShowPopup        bool
	StartsAt         *time.Time
	EndsAt           *time.Time
	Frequency        string
	FrequencyDays    *int16
	MaxPerPeriod     *int16
	MaxTotal         *int16
	Priority         int16
	PopupSize        string
	CtaLabel         []byte
	CtaUrl           *string
	Revision         int32
	ID               uuid.UUID
}

// The content, the revision and the sender role; the dates of publishing, the count and the status are not touched.
func (q *Queries) UpdateAnnouncement(ctx context.Context, arg UpdateAnnouncementParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAnnouncement,
		arg.SenderRole,
		arg.Audience,
		arg.Targeting,
		arg.Type,
		arg.Title,
		arg.Body,
		arg.SendNotification,
		arg.ShowPopup,
		arg.StartsAt,
		arg.EndsAt,
		arg.Frequency,
		arg.FrequencyDays,
		arg.MaxPerPeriod,
		arg.MaxTotal,
		arg.Priority,
		arg.PopupSize,
		arg.CtaLabel,
		arg.CtaUrl,
		arg.Revision,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

